INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_BABE', 'Ba Bể - Hồ xanh và bản làng Tày', 'Chuyến đi 2 ngày về hồ Ba Bể, động Puông và bản Pác Ngòi, dành cho khách muốn nghỉ ngắn ngày trong không gian yên tĩnh, gần thiên nhiên và văn hóa bản địa.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Thuyền hồ Ba Bể, vé tham quan\r\n- Homestay, bữa ăn địa phương và hướng dẫn viên\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT và tips', '2', '3400000.00', '0.00', '0', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_BUONMATHUOT', 'Buôn Ma Thuột - Cà phê và thác Dray Nur', 'Khám phá Buôn Ma Thuột qua hương cà phê, văn hóa Tây Nguyên và vẻ đẹp mạnh mẽ của thác Dray Nur. Trong 3 ngày, tour đưa du khách đến bảo tàng cà phê, Buôn Đôn và các không gian văn hóa bản địa, tạo nên chuyến đi giàu trải nghiệm, gần gũi thiên nhiên và con người địa phương.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan bảo tàng cà phê, Buôn Đôn và thác Dray Nur\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '4000000.00', '0.00', '0', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_CAMAU', 'Cà Mau - Mũi đất cuối trời và rừng ngập mặn', 'Tour 4 ngày đi qua Cà Mau, Đất Mũi, rừng U Minh và các tuyến sông nước đặc trưng miền cực Nam. Lịch trình nhấn mạnh trải nghiệm cộng đồng, ẩm thực địa phương và hoạt động bảo tồn hệ sinh thái ngập mặn.\r\n\r\nBao gồm:\r\n- Xe và tàu tham quan theo chương trình\r\n- Vé vào khu du lịch Đất Mũi, rừng U Minh\r\n- Lưu trú, bữa ăn và hướng dẫn viên\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Phụ phí phòng đơn\r\n- VAT và tips', '4', '6800000.00', '5.00', '1', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_CANTHO', 'Cần Thơ - Chợ nổi và miệt vườn sông nước', 'Trải nghiệm nhịp sống miền Tây qua hành trình Cần Thơ, chợ nổi Cái Răng và miệt vườn sông nước, nơi du khách được cảm nhận sự mộc mạc, hào sảng và giàu bản sắc của vùng đất phù sa. Lịch trình 3 ngày nhẹ nhàng, nhiều hoạt động đời sống địa phương và phù hợp cho gia đình, nhóm bạn hoặc khách muốn nghỉ ngắn ngày.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan chợ nổi Cái Răng và miệt vườn\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '3500000.00', '4.64', '14', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_CONDAO', 'Côn Đảo - Biển hoang sơ và ký ức lịch sử', 'Đến Côn Đảo để cảm nhận vẻ đẹp hoang sơ của biển đảo và chiều sâu lịch sử qua những điểm đến giàu ký ức. Trong 4 ngày, tour kết hợp nghỉ biển, tham quan di tích, trải nghiệm thiên nhiên và hoạt động bảo vệ môi trường, mang đến một chuyến đi yên bình nhưng nhiều dư âm.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Côn Đảo, di tích lịch sử và bãi biển\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '4', '8300000.00', '0.00', '0', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_DALAT', 'Đà Lạt - Rừng thông và nông trại xanh', 'Khám phá Đà Lạt theo cách trọn vẹn nhất cùng hành trình Đà Lạt - Rừng thông và nông trại xanh, nơi mỗi điểm dừng không chỉ là một chuyến tham quan mà còn là trải nghiệm đáng nhớ về văn hóa, thiên nhiên và con người bản địa. Với lịch trình 3 ngày, tour được thiết kế hài hòa giữa nghỉ dưỡng, khám phá và các hoạt động trải nghiệm xanh, mang đến cảm giác thư thái nhưng vẫn đầy cảm hứng cho mọi du khách để bạn tận hưởng chuyến đi một cách tiện lợi, an toàn và đáng nhớ cùng Digital Travel.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan nông trại xanh và các điểm trong lịch trình\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '3900000.00', '0.00', '0', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_DANANG', 'Đà Nẵng - Di sản miền Trung xanh', 'Tận hưởng miền Trung năng động cùng hành trình Đà Nẵng, Sơn Trà, Hội An và Mỹ Sơn, nơi biển xanh, di sản và ẩm thực địa phương hòa quyện trong một chuyến đi giàu cảm xúc. Với lịch trình 4 ngày, tour được thiết kế để du khách vừa có thời gian khám phá các biểu tượng nổi bật vừa nghỉ ngơi thoải mái trong không gian thân thiện và an toàn.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Sơn Trà, Hội An và Mỹ Sơn\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '4', '6200000.00', '4.60', '5', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_HAGIANG', 'Hà Giang - Cung đường đá và chợ phiên', 'Chạm vào vẻ đẹp hùng vĩ của miền cực Bắc qua cung đường đá Hà Giang, nơi cao nguyên đá, chợ phiên, bản làng và những khúc cua đèo tạo nên một hành trình đầy cảm hứng. Với 4 ngày di chuyển và khám phá, tour phù hợp cho du khách yêu thiên nhiên, văn hóa vùng cao và những trải nghiệm chân thực trên đường.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan cao nguyên đá và các điểm chợ phiên\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '4', '5900000.00', '5.00', '2', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_HALONG', 'Hạ Long - Du thuyền vịnh xanh', 'Khám phá Hạ Long trên du thuyền giữa vịnh xanh, nơi những dãy núi đá vôi, làn nước êm và khoảnh khắc hoàng hôn tạo nên trải nghiệm nghỉ dưỡng đáng nhớ. Lịch trình 3 ngày kết hợp tham quan, thư giãn trên tàu và khám phá Cát Bà, phù hợp cho du khách muốn tận hưởng một chuyến đi tiện nghi nhưng vẫn gần gũi thiên nhiên.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Vịnh Hạ Long và Cát Bà\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '5600000.00', '4.80', '5', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_HOIAN', 'Hội An - Phố cổ và làng rau Trà Quế', 'Dạo bước qua Hội An với phố cổ, làng rau Trà Quế và những trải nghiệm văn hóa nhẹ nhàng, nơi từng con phố, món ăn và nếp sống địa phương đều mang nét duyên riêng. Lịch trình 3 ngày kết hợp tham quan di sản, trải nghiệm ẩm thực và hoạt động cộng đồng, phù hợp cho du khách yêu sự chậm rãi và tinh tế.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan phố cổ Hội An và làng rau Trà Quế\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '4400000.00', '4.83', '6', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_HUE', 'Huế - Kinh thành và ẩm thực cố đô', 'Đi qua chiều sâu văn hóa cố đô cùng hành trình Huế - Kinh thành và ẩm thực, nơi du khách được khám phá Đại Nội, lăng tẩm, làng nghề và những hương vị tinh tế của đất kinh kỳ. Lịch trình 3 ngày mang nhịp điệu chậm rãi, giàu chất văn hóa và phù hợp với du khách yêu lịch sử, kiến trúc và ẩm thực địa phương.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Đại Nội, lăng tẩm và làng nghề\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '4100000.00', '4.67', '9', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_MOCCHAU', 'Mộc Châu - Đồi chè và mùa hoa cao nguyên', 'Tận hưởng Mộc Châu trong sắc xanh của đồi chè, mùa hoa cao nguyên và không khí trong lành của núi rừng Tây Bắc. Lịch trình 2 ngày được thiết kế gọn gàng, dễ đi, phù hợp cho chuyến nghỉ cuối tuần với các điểm tham quan thiên nhiên, nông trại và văn hóa địa phương.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan đồi chè, nông trại và điểm mùa hoa\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '2', '2600000.00', '4.00', '1', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_MUINE', 'Mũi Né - Đồi cát và biển xanh Phan Thiết', 'Tận hưởng Mũi Né với đồi cát, làng chài và biển xanh Phan Thiết, nơi nắng gió miền duyên hải mang đến một chuyến đi rực rỡ và thư thái. Lịch trình 3 ngày kết hợp tham quan, nghỉ biển và thưởng thức đặc sản địa phương, phù hợp cho nhóm bạn, gia đình và những ai yêu không khí biển.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan đồi cát, làng chài Mũi Né và các điểm biển\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '4700000.00', '4.40', '5', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_NINHBINH', 'Ninh Bình - Tràng An và chùa Bái Đính', 'Du ngoạn Ninh Bình với hành trình Tràng An, Hoa Lư và chùa Bái Đính, nơi cảnh quan non nước, di sản cố đô và không gian tâm linh tạo nên một chuyến đi nhẹ nhàng nhưng sâu lắng. Lịch trình 2 ngày phù hợp cho du khách muốn đổi gió cuối tuần, trải nghiệm văn hóa miền Bắc và tận hưởng dịch vụ được sắp xếp gọn gàng.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Tràng An, Hoa Lư và chùa Bái Đính\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '2', '2800000.00', '4.75', '4', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_PHONGNHA', 'Phong Nha - Hang động kỳ quan và sông Son', 'Hành trình 3 ngày khám phá Phong Nha, động Thiên Đường, sông Chày - hang Tối và nhịp sống ven sông Son. Tour phù hợp cho nhóm bạn, gia đình yêu thiên nhiên và khách muốn kết hợp trải nghiệm hang động với nghỉ dưỡng nhẹ.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan hang động và thuyền sông Son\r\n- Lưu trú, bữa ăn và hướng dẫn viên\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT và tips', '3', '5200000.00', '4.00', '1', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_PHUQUOC', 'Phú Quốc - Biển xanh và hoàng hôn Nam Đảo', 'Tận hưởng Phú Quốc với hành trình biển xanh, hoàng hôn Nam Đảo và những trải nghiệm nghỉ dưỡng thư thái giữa thiên nhiên đảo ngọc. Trong 4 ngày, du khách được kết hợp tham quan, tắm biển, khám phá đặc sản địa phương và nghỉ ngơi theo nhịp chậm rãi, phù hợp cho gia đình, cặp đôi và nhóm bạn.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Nam Đảo và các điểm trong lịch trình\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '4', '7600000.00', '4.60', '5', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_PULUONG', 'Pù Luông - Ruộng bậc thang và bản làng', 'Trở về nhịp sống an yên của Pù Luông với ruộng bậc thang, bản làng và những cung đường đi bộ nhẹ giữa thung lũng xanh. Lịch trình 2 ngày phù hợp cho du khách muốn tạm rời phố thị, nghỉ tại không gian gần gũi thiên nhiên và trải nghiệm văn hóa cộng đồng một cách vừa sức.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Pù Luông, bản làng và ruộng bậc thang\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '2', '3200000.00', '5.00', '1', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_QUYNHON', 'Quy Nhơn - Kỳ Co Eo Gió và làng chài', 'Khám phá Quy Nhơn qua Kỳ Co, Eo Gió và những làng chài ven biển, nơi vẻ đẹp biển xanh, vách đá và ẩm thực miền Trung tạo nên một hành trình đầy năng lượng. Với 3 ngày, tour cân bằng giữa tham quan, nghỉ biển và trải nghiệm đời sống địa phương, phù hợp cho du khách thích biển và những khung cảnh rộng mở.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Kỳ Co, Eo Gió và làng chài\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '5200000.00', '5.00', '2', NULL, NULL);
INSERT INTO `tour_maus` (`ma_tour_mau`, `tieu_de`, `mo_ta`, `thoi_luong`, `gia_san`, `danh_gia`, `so_danh_gia`, `created_at`, `updated_at`) VALUES ('TM_SAPA', 'Sa Pa - Săn mây Fansipan và bản Cát Cát', 'Khám phá Sa Pa theo cách trọn vẹn nhất cùng hành trình săn mây Fansipan và bản Cát Cát, nơi du khách được chạm vào vẻ đẹp núi rừng Tây Bắc, văn hóa bản địa và nhịp sống bình yên giữa mây trời. Với lịch trình 3 ngày, tour cân bằng giữa tham quan, nghỉ dưỡng và trải nghiệm địa phương, phù hợp cho gia đình, nhóm bạn và du khách yêu thiên nhiên.\r\n\r\nBao gồm:\r\n- Xe đưa đón theo chương trình\r\n- Vé tham quan Fansipan và bản Cát Cát\r\n- Lưu trú và bữa ăn theo lịch trình\r\n- Hướng dẫn viên du lịch\r\nKhông bao gồm:\r\n- Chi phí cá nhân\r\n- Đồ uống ngoài chương trình\r\n- VAT\r\n- Tips cho hướng dẫn viên và tài xế', '3', '4500000.00', '4.60', '10', NULL, NULL);
