INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_BB_NEW_01', 'TM_BABE', '1', '06:45 - Dùng bữa sáng và nghe hướng dẫn lịch trình trong ngày.\n09:00 - Di chuyển lên Ba Bể, đi thuyền trên hồ, nhận homestay và ăn tối cùng gia đình địa phương\n11:45 - Thưởng thức bữa trưa với món ăn đặc trưng địa phương.\n15:00 - Tham quan bổ sung và tìm hiểu cảnh quan thiên nhiên tại điểm đến.\n18:00 - Nhận phòng hoặc nghỉ ngơi tại điểm dừng chân theo chương trình.', NULL, 'Sáng: Buffet khách sạn | Trưa: Cá hồ nướng, lợn bản, rau rừng | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_BB_NEW_02', 'TM_BABE', '2', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Tham quan động Puông, mua đặc sản, ăn trưa và về lại Hà Nội\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Sáng: Buffet khách sạn | Trưa: Xôi ngũ sắc, gà đồi | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_BMT_01', 'TM_BUONMATHUOT', '1', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Trải nghiệm văn hóa cà phê và không gian Tây Nguyên\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Sáng: Buffet khách sạn | Trưa: Gà nướng cơm lam | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_BMT_02', 'TM_BUONMATHUOT', '2', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Tham quan thác, tìm hiểu văn hóa Ê Đê và M''Nông\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Cơm lam, thịt nướng', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_BMT_03', 'TM_BUONMATHUOT', '3', '06:45 - Dùng bữa sáng và nghe hướng dẫn lịch trình trong ngày.\n09:00 - Thưởng thức cà phê, mua quà và ra sân bay\n11:45 - Thưởng thức bữa trưa với món ăn đặc trưng địa phương.\n15:00 - Tham quan bổ sung và tìm hiểu cảnh quan thiên nhiên tại điểm đến.\n18:00 - Nhận phòng hoặc nghỉ ngơi tại điểm dừng chân theo chương trình.', NULL, 'Sáng: Buffet khách sạn | Trưa: Bún đỏ Buôn Ma Thuột | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_CANTHO_01', 'TM_CANTHO', '1', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Đón khách và tham quan bến Ninh Kiều buổi tối\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Sáng: Buffet khách sạn | Trưa: Lẩu mắm miền Tây | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_CANTHO_02', 'TM_CANTHO', '2', '07:00 - Tập trung, kiểm tra hành lý và bắt đầu lịch trình trong ngày.\n08:30 - Đi chợ nổi sớm, thăm vườn trái cây và làm bánh dân gian\n12:00 - Dùng bữa trưa theo thực đơn của chương trình.\n14:30 - Trải nghiệm cảnh quan và văn hóa địa phương theo hành trình.\n19:00 - Về nơi lưu trú, nghỉ ngơi và chuẩn bị cho ngày tiếp theo.', NULL, 'Sáng: Buffet khách sạn | Trưa: Cá lóc nướng trui | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_CANTHO_03', 'TM_CANTHO', '3', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Tham quan nhà cổ, mua đặc sản và kết thúc chương trình\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Sáng: Buffet khách sạn | Trưa: Hủ tiếu Nam Vang | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_CM_NEW_01', 'TM_CAMAU', '1', '07:00 - Tập trung, kiểm tra hành lý và bắt đầu lịch trình trong ngày.\n08:30 - Đón khách, nhận phòng, tham quan chợ đêm và nghe giới thiệu văn hóa miền cực Nam\n12:00 - Dùng bữa trưa theo thực đơn của chương trình.\n14:30 - Trải nghiệm cảnh quan và văn hóa địa phương theo hành trình.\n19:00 - Về nơi lưu trú, nghỉ ngơi và chuẩn bị cho ngày tiếp theo.', NULL, 'Sáng: Buffet khách sạn | Trưa: Lẩu mắm, rau đồng | Chiều: Trái cây nhẹ', NULL, NULL);
INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_CM_NEW_02', 'TM_CAMAU', '2', '07:00 - Tập trung, kiểm tra hành lý và bắt đầu lịch trình trong ngày.\n08:30 - Đi tàu đến Đất Mũi, tham quan rừng ngập mặn và điểm cực Nam Tổ quốc\n12:00 - Dùng bữa trưa theo thực đơn của chương trình.\n14:30 - Trải nghiệm cảnh quan và văn hóa địa phương theo hành trình.\n19:00 - Về nơi lưu trú, nghỉ ngơi và chuẩn bị cho ngày tiếp theo.', NULL, 'Sáng: Buffet khách sạn | Trưa: Cua Cà Mau, cá thòi lòi nướng | Chiều: Trái cây nhẹ', NULL, NULL);
