INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_QUYNHON_03', 'TM_QUYNHON', '3', '06:30 - Dùng bữa sáng và chuẩn bị cho lịch trình trong ngày.\n08:00 - Trải nghiệm làng chài, mua đặc sản và kết thúc tour\n11:30 - Dùng bữa trưa theo thực đơn của chương trình.\n14:00 - Khám phá cảnh quan thiên nhiên và tìm hiểu nét đặc trưng của điểm đến.\n18:30 - Nghỉ ngơi tại nơi lưu trú hoặc điểm dừng chân đã bố trí.', NULL, 'Sáng: Buffet khách sạn | Trưa: Cơm nhà hàng biển | Chiều: Trái cây nhẹ', NULL, NULL);
