INSERT INTO `lich_trinh_tours` (`ma_lich_trinh_tour`, `ma_tour_mau`, `ngay_thu`, `hoat_dong`, `mo_ta`, `thuc_don`, `created_at`, `updated_at`) VALUES ('LTT_SAPA_02', 'TM_SAPA', '2', '07:00 - Tập trung, kiểm tra hành lý và bắt đầu lịch trình trong ngày.\n08:30 - Săn mây Fansipan và tự do khám phá thị trấn\n12:00 - Dùng bữa trưa theo thực đơn của chương trình.\n14:30 - Trải nghiệm cảnh quan và văn hóa địa phương theo hành trình.\n19:00 - Về nơi lưu trú, nghỉ ngơi và chuẩn bị cho ngày tiếp theo.', NULL, 'Sáng: Buffet khách sạn | Trưa: Lẩu cá tầm | Chiều: Trái cây nhẹ', NULL, NULL);
